struct RbMotor { int pwm = -1, ina = -1, inb = -1; };
static RbMotor motores_puente[4];
inline int motores_indice(const String& motor) { return motor.length() == 1 ? motor[0] - 'A' : -1; }
inline void motores_configurar(const String& motor, int pwm, int ina, int inb) {
    int i = motores_indice(motor); if (i < 0 || i > 3) return;
    motores_puente[i].pwm = pwm; motores_puente[i].ina = ina; motores_puente[i].inb = inb;
    pinMode(pwm, OUTPUT); pinMode(ina, OUTPUT); pinMode(inb, OUTPUT);
    digitalWrite(ina, LOW); digitalWrite(inb, LOW); analogWrite(pwm, 0);
}
inline void motores_parar(RbMotor& m, bool frenar) {
    digitalWrite(m.ina, frenar ? HIGH : LOW); digitalWrite(m.inb, frenar ? HIGH : LOW);
    analogWrite(m.pwm, frenar ? {PWM_MAX} : 0);
}
inline void motores_velocidad(const String& motor, float velocidad, const char* bloque) {
    int i = motores_indice(motor);
    if (i < 0 || i > 3 || motores_puente[i].pwm < 0) { rb_fail(bloque, "Motor sin configurar: usa configurar motor al iniciar"); return; }
    velocidad = fmaxf(-100, fminf(100, rb_finite(velocidad, bloque)));
    RbMotor& m = motores_puente[i];
    if (velocidad == 0) { motores_parar(m, false); return; }
    digitalWrite(m.ina, velocidad > 0 ? HIGH : LOW); digitalWrite(m.inb, velocidad > 0 ? LOW : HIGH);
