def memoria_datos(bloque):
    try:
        with open("memoria.json", "r") as archivo:
            datos = json.load(archivo)
    except OSError as error:
        if error.args and error.args[0] == 2:
            return {}
        rb_fail(bloque, "No se pudo acceder a la memoria")
    except ValueError:
        rb_fail(bloque, "Memoria danada: borra los numeros guardados")
    if not isinstance(datos, dict) or any(not isinstance(v, (int, float)) or isinstance(v, bool) for v in datos.values()):
        rb_fail(bloque, "Memoria danada: borra los numeros guardados")
    return datos

def memoria_volcar(datos, bloque):
    try:
        with open("memoria.json.tmp", "w") as archivo:
            json.dump(datos, archivo)
            archivo.flush()
        os.rename("memoria.json.tmp", "memoria.json")
    except (OSError, ValueError):
        rb_fail(bloque, "No se pudo acceder a la memoria")

