// Formato v1: GFM1, versión, reservado, CRC16-CCITT (little endian), 16 × (nombre[12], float32 LE).
static const int memoria_bytes = 264;
inline uint16_t memoria_crc(const uint8_t* datos) {
    uint16_t crc = 0xffff;
    for (int i = 8; i < memoria_bytes; i++) {
        crc ^= uint16_t(datos[i]) << 8;
        for (int bit = 0; bit < 8; bit++) crc = (crc & 0x8000) ? uint16_t((crc << 1) ^ 0x1021) : uint16_t(crc << 1);
    }
    return crc;
}
inline void memoria_vacia(uint8_t* datos) {
    memset(datos, 0, memoria_bytes);
    datos[0] = 'G'; datos[1] = 'F'; datos[2] = 'M'; datos[3] = '1'; datos[4] = 1;
}
inline bool memoria_tabla(uint8_t* datos, const char* bloque) {
    if (EEPROM.length() < memoria_bytes) { rb_fail(bloque, "No se pudo acceder a la memoria"); return false; }
    bool virgen = true;
    for (int i = 0; i < memoria_bytes; i++) { datos[i] = EEPROM.read(i); if (datos[i] != 0xff) virgen = false; }
    // EEPROM nueva o con datos de otro programa (sin la firma GFM1): se usa como tabla vacía.
    bool propia = datos[0] == 'G' && datos[1] == 'F' && datos[2] == 'M' && datos[3] == '1' && datos[4] == 1 && datos[5] == 0;
    if (virgen || !propia) { memoria_vacia(datos); return true; }
    uint16_t crc = memoria_crc(datos);
    if (datos[6] != uint8_t(crc) || datos[7] != uint8_t(crc >> 8)) {
        rb_fail(bloque, "Memoria danada: borra los numeros guardados"); return false;
    }
    return true;
}
inline void memoria_volcar(uint8_t* datos, const char* bloque) {
    if (EEPROM.length() < memoria_bytes) { rb_fail(bloque, "No se pudo acceder a la memoria"); return; }
    uint16_t crc = memoria_crc(datos);
    datos[6] = uint8_t(crc); datos[7] = uint8_t(crc >> 8);
    for (int i = 0; i < memoria_bytes; i++) if (EEPROM.read(i) != datos[i]) EEPROM.write(i, datos[i]);
}
inline int memoria_indice(const uint8_t* datos, const String& nombre) {
    for (int i = 0; i < 16; i++) {
        bool igual = true;
        for (int c = 0; c < 12; c++) if (datos[8 + i * 16 + c] != (c < int(nombre.length()) ? uint8_t(nombre[c]) : 0)) igual = false;
        if (igual) return i;
    }
    return -1;
}
inline bool memoria_buscar(const String& nombre, float& valor, bool& existe, const char* bloque) {
    uint8_t datos[memoria_bytes];
    if (!memoria_tabla(datos, bloque)) return false;
    int indice = memoria_indice(datos, nombre);
    existe = indice >= 0;
    if (existe) {
        uint32_t bits = 0;
        for (int c = 0; c < 4; c++) bits |= uint32_t(datos[8 + indice * 16 + 12 + c]) << (8 * c);
        memcpy(&valor, &bits, 4);
    }
    return true;
}
inline void memoria_escribir(const String& nombre, float valor, const char* bloque) {
    uint8_t datos[memoria_bytes];
    if (!memoria_tabla(datos, bloque)) return;
    int indice = memoria_indice(datos, nombre);
    if (indice < 0) for (int i = 0; i < 16; i++) if (datos[8 + i * 16] == 0) { indice = i; break; }
    if (indice < 0) { rb_fail(bloque, "Memoria llena: maximo 16 numeros"); return; }
    for (int c = 0; c < 12; c++) datos[8 + indice * 16 + c] = c < int(nombre.length()) ? uint8_t(nombre[c]) : 0;
    uint32_t bits = 0;
    static_assert(sizeof(float) == 4, "Memoria requiere float de 32 bits");
    memcpy(&bits, &valor, 4);
    for (int c = 0; c < 4; c++) datos[8 + indice * 16 + 12 + c] = uint8_t(bits >> (8 * c));
    memoria_volcar(datos, bloque);
}
inline void memoria_borrar(const char* bloque) {
    uint8_t datos[memoria_bytes];
    memoria_vacia(datos);
    memoria_volcar(datos, bloque);
}
